import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BbWZUwfl.js";const g=JSON.parse('{"title":"Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1794305742000}'),o={name:"guide.md"};function n(l,e,s,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>Mandatory conventional-commit, branching, PR, and release standards for Mediusware contributors.</p><p>](<a href="https://mediuswareltd.github.io/conventional-commit-spec/" target="_blank" rel="noreferrer">https://mediuswareltd.github.io/conventional-commit-spec/</a>)</p><p>Last Updated: January 2026<br> Status: Mandatory for All Contributors</p><h2 id="table-of-contents" tabindex="-1"><strong>Table of Contents</strong> <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;**Table of Contents**&quot;">​</a></h2><ol><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#overview" target="_blank" rel="noreferrer">Overview</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#branching-strategy" target="_blank" rel="noreferrer">Branching Strategy</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#branch-naming-conventions" target="_blank" rel="noreferrer">Branch Naming Conventions</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#identity-authentication" target="_blank" rel="noreferrer">Identity &amp; Authentication</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#commit-standards" target="_blank" rel="noreferrer">Commit Standards</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#pull-request-guidelines" target="_blank" rel="noreferrer">Pull Request Guidelines</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#merge-conflict-resolution" target="_blank" rel="noreferrer">Merge Conflict Resolution</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#rebase-force-push-policy" target="_blank" rel="noreferrer">Rebase &amp; Force Push Policy</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#branch-sync-ci-requirements" target="_blank" rel="noreferrer">Branch Sync &amp; CI Requirements</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#release-management" target="_blank" rel="noreferrer">Release Management</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#dependency-management" target="_blank" rel="noreferrer">Dependency Management</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#prohibited-practices" target="_blank" rel="noreferrer">Prohibited Practices</a></li><li><a href="https://docs.google.com/document/d/17KE9KSB7VgfJ9CBPwXa5YarqekPIqFvIiQKbGTm4Vso/edit?tab=t.0#enforcement" target="_blank" rel="noreferrer">Enforcement</a></li></ol><h2 id="overview" tabindex="-1"><strong>Overview</strong> <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;**Overview**&quot;">​</a></h2><p>This document establishes mandatory Git practices for all project contributors. These standards ensure clean history, safe releases, clear ownership, and predictable delivery. Following these practices helps maintain a consistent workflow across teams, reduces the risk of errors during integration, and improves collaboration between developers. It also ensures that code is traceable, auditable, and easier to maintain over time. Adhering to these standards supports faster code reviews, smoother deployments, and a more reliable production environment.</p><p><strong>Applicability: All team members including leads.</strong></p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><h2 id="branching-strategy" tabindex="-1"><strong>Branching Strategy</strong> <a class="header-anchor" href="#branching-strategy" aria-label="Permalink to &quot;**Branching Strategy**&quot;">​</a></h2><p>Branching strategy organizes development by isolating work in feature branches and merging through dev, staging, then main to keep production stable.</p><h3 id="permanent-branches" tabindex="-1"><strong>Permanent Branches</strong> <a class="header-anchor" href="#permanent-branches" aria-label="Permalink to &quot;**Permanent Branches**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Branch</th><th>Purpose</th><th>Stability</th><th>Source</th></tr></thead><tbody><tr><td>main</td><td>Production code</td><td>Must always be stable</td><td>staging only</td></tr><tr><td>staging</td><td>Pre-production, QA, UAT</td><td>Should be stable</td><td>dev only</td></tr><tr><td>dev</td><td>Active development</td><td>May be unstable</td><td>Feature branches</td></tr></tbody></table><h3 id="workflow" tabindex="-1"><strong>Workflow</strong> <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;**Workflow**&quot;">​</a></h3><p>feature/xyz → dev → staging → main<br> bugfix/abc → dev → staging → main<br> chore/def → dev → staging → main</p><h3 id="rules" tabindex="-1"><strong>Rules</strong> <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;**Rules**&quot;">​</a></h3><ul><li>No direct commits to main or staging</li><li>All work starts in a feature branch</li><li>Never rebase dev, staging, or main</li></ul><h2 id="branch-naming-conventions" tabindex="-1"><strong>Branch Naming Conventions</strong> <a class="header-anchor" href="#branch-naming-conventions" aria-label="Permalink to &quot;**Branch Naming Conventions**&quot;">​</a></h2><p>Branch naming conventions make branch purpose and type clear and consistent.</p><h3 id="format" tabindex="-1"><strong>Format</strong> <a class="header-anchor" href="#format" aria-label="Permalink to &quot;**Format**&quot;">​</a></h3><p>&lt;type&gt;/&lt;brief-description&gt;</p><h3 id="allowed-types" tabindex="-1"><strong>Allowed Types</strong> <a class="header-anchor" href="#allowed-types" aria-label="Permalink to &quot;**Allowed Types**&quot;">​</a></h3><ul><li>feature or feat/ - New functionality</li><li>bugfix or fix/ - Bug corrections</li><li>hotfix/ - Critical production fixes</li><li>chore/ - Maintenance tasks</li></ul><h3 id="examples" tabindex="-1"><strong>Examples</strong> <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;**Examples**&quot;">​</a></h3><p>feature/analytics-localization<br> bugfix/login-token-expiry<br> hotfix/payment-gateway-timeout<br> chore/update-eslint-config</p><p>Rules:</p><ul><li>Use lowercase with hyphens</li><li>Be descriptive but concise</li><li>Maximum 50 characters</li></ul><h2 id="identity-authentication" tabindex="-1"><strong>Identity &amp; Authentication</strong> <a class="header-anchor" href="#identity-authentication" aria-label="Permalink to &quot;**Identity &amp; Authentication**&quot;">​</a></h2><p>Ensure commits use personal GitHub accounts with correct name/email for identity verification.</p><h3 id="github-account-requirements" tabindex="-1"><strong>GitHub Account Requirements</strong> <a class="header-anchor" href="#github-account-requirements" aria-label="Permalink to &quot;**GitHub Account Requirements**&quot;">​</a></h3><ol><li>Use your personal GitHub account</li><li>Register with company email</li><li>No shared or generic accounts</li></ol><h3 id="commit-identity-configuration" tabindex="-1"><strong>Commit Identity Configuration</strong> <a class="header-anchor" href="#commit-identity-configuration" aria-label="Permalink to &quot;**Commit Identity Configuration**&quot;">​</a></h3><p>git config --global user.name &quot;Rashed&quot;<br> git config --global user.email &quot;<a href="mailto:example@mediusware.com" target="_blank" rel="noreferrer">example@mediusware.com</a>&quot;</p><h3 id="verification" tabindex="-1"><strong>Verification</strong> <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;**Verification**&quot;">​</a></h3><p>git config --global user.name<br> git config --global user.email</p><h3 id="expected-output" tabindex="-1"><strong>Expected Output</strong> <a class="header-anchor" href="#expected-output" aria-label="Permalink to &quot;**Expected Output**&quot;">​</a></h3><p>Author: Rashed &lt;example@mediusware.com&gt;<br> Date: Mon Jan 15 14:30:00 2026 +0600</p><h3 id="ssh-authentication" tabindex="-1"><strong>SSH Authentication</strong> <a class="header-anchor" href="#ssh-authentication" aria-label="Permalink to &quot;**SSH Authentication**&quot;">​</a></h3><ul><li>Shared SSH keys are allowed for authentication only</li><li>SSH access does not define commit identity</li><li>Commit identity is set via git config</li></ul><h3 id="enforcement" tabindex="-1"><strong>Enforcement</strong> <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;**Enforcement**&quot;">​</a></h3><p>Commits with incorrect or missing identity will be rejected during code review.</p><h2 id="commit-standards" tabindex="-1"><strong>Commit Standards</strong> <a class="header-anchor" href="#commit-standards" aria-label="Permalink to &quot;**Commit Standards**&quot;">​</a></h2><p>Commit standards ensure clear, consistent messages showing the type and purpose of each change.</p><h3 id="message-format" tabindex="-1"><strong>Message Format</strong> <a class="header-anchor" href="#message-format" aria-label="Permalink to &quot;**Message Format**&quot;">​</a></h3><p>&lt;type&gt;: &lt;concise description&gt;</p><h3 id="commit-types" tabindex="-1"><strong>Commit Types</strong> <a class="header-anchor" href="#commit-types" aria-label="Permalink to &quot;**Commit Types**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Purpose</th><th>Example</th></tr></thead><tbody><tr><td>feat:</td><td>New feature</td><td>feat: add tenant-based filtering to reports</td></tr><tr><td>fix:</td><td>Bug correction</td><td>fix: resolve token refresh infinite loop</td></tr><tr><td>chore:</td><td>Maintenance</td><td>chore: remove deprecated API endpoints</td></tr><tr><td>refactor:</td><td>Code restructuring</td><td>refactor: simplify authentication middleware</td></tr><tr><td>docs:</td><td>Documentation</td><td>docs: update API integration guide</td></tr><tr><td>test:</td><td>Tests</td><td>test: add unit tests for payment service</td></tr><tr><td>perf:</td><td>Performance</td><td>perf: optimize database query indexes</td></tr><tr><td>style:</td><td>Formatting</td><td>style: apply consistent code formatting</td></tr><tr><td>build:</td><td>Build system</td><td>build: update webpack configuration</td></tr><tr><td>ci:</td><td>CI/CD</td><td>ci: add automated security scanning</td></tr></tbody></table><h3 id="examples-1" tabindex="-1"><strong>Examples</strong> <a class="header-anchor" href="#examples-1" aria-label="Permalink to &quot;**Examples**&quot;">​</a></h3><p>feat: implement OAuth 2.0 social login<br> fix: prevent race condition in order processing<br> chore: update Node.js to v20 LTS</p><h3 id="rules-1" tabindex="-1"><strong>Rules</strong> <a class="header-anchor" href="#rules-1" aria-label="Permalink to &quot;**Rules**&quot;">​</a></h3><ul><li>One logical change per commit</li><li>Use present tense</li><li>Reference issues when applicable</li><li>No WIP commits</li></ul><h2 id="pull-request-guidelines" tabindex="-1"><strong>Pull Request Guidelines</strong> <a class="header-anchor" href="#pull-request-guidelines" aria-label="Permalink to &quot;**Pull Request Guidelines**&quot;">​</a></h2><p>Required PR contents, size limits, and pre-merge checklist for quality control.</p><h3 id="required-contents" tabindex="-1"><strong>Required Contents</strong> <a class="header-anchor" href="#required-contents" aria-label="Permalink to &quot;**Required Contents**&quot;">​</a></h3><p>Every PR must include:</p><ol><li>Description - Clear explanation of changes</li><li>Testing Notes - How changes were verified</li><li>Screenshots - For UI modifications</li><li>Migration Notes - Database or config changes</li><li>Related Issues - Link to tickets</li></ol><h3 id="pr-size-guidelines" tabindex="-1"><strong>PR Size Guidelines</strong> <a class="header-anchor" href="#pr-size-guidelines" aria-label="Permalink to &quot;**PR Size Guidelines**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lines Changed</th><th>Status</th><th>Action Required</th></tr></thead><tbody><tr><td>Less than 400</td><td>Ideal</td><td>Proceed normally</td></tr><tr><td>400 to 500</td><td>Large</td><td>Justify or split</td></tr><tr><td>More than 500</td><td>Too large</td><td>Must split</td></tr></tbody></table><h3 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h3><h3 id="-2" tabindex="-1"><a class="header-anchor" href="#-2" aria-label="Permalink to &quot;&quot;">​</a></h3><h3 id="draft-pull-requests" tabindex="-1"><strong>Draft Pull Requests</strong> <a class="header-anchor" href="#draft-pull-requests" aria-label="Permalink to &quot;**Draft Pull Requests**&quot;">​</a></h3><ul><li>Use for work in progress</li><li>Cannot be merged</li><li>Mark &quot;Ready for Review&quot; only after conflicts resolved and tests passed</li></ul><h3 id="pre-merge-checklist" tabindex="-1"><strong>Pre-Merge Checklist</strong> <a class="header-anchor" href="#pre-merge-checklist" aria-label="Permalink to &quot;**Pre-Merge Checklist**&quot;">​</a></h3><p>Before requesting review:</p><ul><li>Branch synced with target</li><li>No merge conflicts</li><li>All tests passing locally</li><li>No debug logs or commented code</li><li>Commit messages follow standards</li><li>No unrelated changes</li></ul><p>PRs failing this checklist will be rejected.</p><h2 id="merge-conflict-resolution" tabindex="-1"><strong>Merge Conflict Resolution</strong> <a class="header-anchor" href="#merge-conflict-resolution" aria-label="Permalink to &quot;**Merge Conflict Resolution**&quot;">​</a></h2><p>Merge conflict resolution ensures the PR author carefully resolves conflicts, preserves functionality, tests locally, and never force-pushes or drops code silently.</p><h3 id="responsibility" tabindex="-1"><strong>Responsibility</strong> <a class="header-anchor" href="#responsibility" aria-label="Permalink to &quot;**Responsibility**&quot;">​</a></h3><p>The PR author is fully responsible for resolving all merge conflicts.</p><h3 id="resolution-process" tabindex="-1"><strong>Resolution Process</strong> <a class="header-anchor" href="#resolution-process" aria-label="Permalink to &quot;**Resolution Process**&quot;">​</a></h3><h4 id="step-1-sync-with-target" tabindex="-1"><strong>Step 1: Sync with Target</strong> <a class="header-anchor" href="#step-1-sync-with-target" aria-label="Permalink to &quot;**Step 1: Sync with Target**&quot;">​</a></h4><p>git fetch origin<br> git rebase origin/dev</p><p>or</p><p>git merge origin/dev</p><h4 id="step-2-resolve-manually" tabindex="-1"><strong>Step 2: Resolve Manually</strong> <a class="header-anchor" href="#step-2-resolve-manually" aria-label="Permalink to &quot;**Step 2: Resolve Manually**&quot;">​</a></h4><p>Do:</p><ul><li>Understand both versions</li><li>Preserve existing functionality</li><li>Maintain security checks</li><li>Keep tenant isolation</li><li>Retain recent fixes</li></ul><p>Do Not:</p><ul><li>Use &quot;Accept all incoming&quot; blindly</li><li>Use &quot;Accept all current&quot; blindly</li><li>Comment out code</li><li>Remove logic without understanding</li></ul><h4 id="step-3-validate-locally" tabindex="-1"><strong>Step 3: Validate Locally</strong> <a class="header-anchor" href="#step-3-validate-locally" aria-label="Permalink to &quot;**Step 3: Validate Locally**&quot;">​</a></h4><p>npm start<br> npm test</p><p>Verify affected functionality manually.</p><h4 id="step-4-commit-resolution" tabindex="-1"><strong>Step 4: Commit Resolution</strong> <a class="header-anchor" href="#step-4-commit-resolution" aria-label="Permalink to &quot;**Step 4: Commit Resolution**&quot;">​</a></h4><p>git add .<br> git commit -m &quot;fix: resolve merge conflicts with dev&quot;</p><h3 id="strictly-forbidden" tabindex="-1"><strong>Strictly Forbidden</strong> <a class="header-anchor" href="#strictly-forbidden" aria-label="Permalink to &quot;**Strictly Forbidden**&quot;">​</a></h3><ul><li>Force push to dev, staging, main</li><li>Pushing conflict markers</li><li>Resolving conflicts without testing</li><li>Silently dropping code</li></ul><p>Violations are treated as critical incidents.</p><h2 id="rebase-force-push-policy" tabindex="-1"><strong>Rebase &amp; Force Push Policy</strong> <a class="header-anchor" href="#rebase-force-push-policy" aria-label="Permalink to &quot;**Rebase &amp; Force Push Policy**&quot;">​</a></h2><p>Rules limiting rebase to personal branches and force-push restrictions.</p><h3 id="rebase-usage" tabindex="-1"><strong>Rebase Usage</strong> <a class="header-anchor" href="#rebase-usage" aria-label="Permalink to &quot;**Rebase Usage**&quot;">​</a></h3><p>Allowed:</p><ul><li>Personal feature branches only</li></ul><p>Forbidden:</p><ul><li>dev, staging, main</li><li>Branches with multiple collaborators</li></ul><h3 id="force-push-rules" tabindex="-1"><strong>Force Push Rules</strong> <a class="header-anchor" href="#force-push-rules" aria-label="Permalink to &quot;**Force Push Rules**&quot;">​</a></h3><p>Allowed:</p><p>git push --force-with-lease origin feature/my-work</p><p>Forbidden:</p><p>git push --force origin dev<br> git push --force origin staging<br> git push --force origin main</p><h2 id="branch-sync-ci-requirements" tabindex="-1"><strong>Branch Sync &amp; CI Requirements</strong> <a class="header-anchor" href="#branch-sync-ci-requirements" aria-label="Permalink to &quot;**Branch Sync &amp; CI Requirements**&quot;">​</a></h2><p>Branch sync ensures feature branches stay updated, CI must pass before merging, and all main merges are tagged for traceable releases.</p><h3 id="branch-sync-discipline" tabindex="-1"><strong>Branch Sync Discipline</strong> <a class="header-anchor" href="#branch-sync-discipline" aria-label="Permalink to &quot;**Branch Sync Discipline**&quot;">​</a></h3><ul><li>Feature branches must sync with dev every 2-3 days</li><li>Inactive branches (14+ days) may be closed</li></ul><h3 id="ci-requirements" tabindex="-1"><strong>CI Requirements</strong> <a class="header-anchor" href="#ci-requirements" aria-label="Permalink to &quot;**CI Requirements**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Condition</th><th>Action</th></tr></thead><tbody><tr><td>All checks pass</td><td>Merge allowed</td></tr><tr><td>Any check fails</td><td>Merge blocked</td></tr></tbody></table><h3 id="-3" tabindex="-1"><a class="header-anchor" href="#-3" aria-label="Permalink to &quot;&quot;">​</a></h3><h3 id="rules-2" tabindex="-1"><strong>Rules</strong> <a class="header-anchor" href="#rules-2" aria-label="Permalink to &quot;**Rules**&quot;">​</a></h3><ul><li>CI failures block merge</li><li>&quot;Works locally&quot; is not acceptable</li><li>CI bypass is not allowed</li></ul><h2 id="release-management" tabindex="-1"><strong>Release Management</strong> <a class="header-anchor" href="#release-management" aria-label="Permalink to &quot;**Release Management**&quot;">​</a></h2><p>Tagging policy for every main merge and structured revert procedures.</p><h3 id="tagging-policy" tabindex="-1"><strong>Tagging Policy</strong> <a class="header-anchor" href="#tagging-policy" aria-label="Permalink to &quot;**Tagging Policy**&quot;">​</a></h3><p>Every merge to main must be tagged:</p><p>git tag -a v1.4.0 -m &quot;Release version 1.4.0&quot;<br> git push origin v1.4.0</p><h3 id="tag-format" tabindex="-1"><strong>Tag Format</strong> <a class="header-anchor" href="#tag-format" aria-label="Permalink to &quot;**Tag Format**&quot;">​</a></h3><p>v&lt;major&gt;.&lt;minor&gt;.&lt;patch&gt;[-suffix]</p><p>Examples:</p><ul><li>v1.3.0 - Standard release</li><li>v1.3.1 - Patch release</li><li>v1.3.1-hotfix - Emergency fix</li></ul><h3 id="benefits" tabindex="-1"><strong>Benefits</strong> <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;**Benefits**&quot;">​</a></h3><ul><li>Rollback capability</li><li>Audit trail</li><li>Production debugging</li></ul><h3 id="revert-policy" tabindex="-1"><strong>Revert Policy</strong> <a class="header-anchor" href="#revert-policy" aria-label="Permalink to &quot;**Revert Policy**&quot;">​</a></h3><ul><li>Prefer revert over panic fixes</li><li>Fix forward in a new PRI can help with text formatting by <strong>generating or rewriting content</strong> to meet a specific structure or style. For example, I can:</li><li><strong>Create lists and tables</strong> based on your request.</li><li><strong>Format generated text</strong> using bold, italics, or headings.</li><li><strong>Rewrite existing text</strong> from your document into a different format (e.g., turning a paragraph into a bulleted list).</li></ul><p>For instance, if you highlight a section and ask me to &quot;turn this into a numbered list&quot; or &quot;summarize this using bold headings,&quot; I can generate that content for you.</p><p>However, I <strong>cannot</strong> directly apply formatting <em>changes</em> to the existing text in the document, such as:</p><ul><li>Changing the font, font size, or color.</li><li>Applying specific styles (like &#39;Heading 1&#39; or &#39;Normal text&#39;).</li><li>Adding comments or tracked changes.</li></ul><p>How would you like me to help format some text in your document, &quot;Standard Git Practice Discipline&quot;?</p><ul><li>Reverts must reference original PR</li></ul><h2 id="dependency-management" tabindex="-1"><strong>Dependency Management</strong> <a class="header-anchor" href="#dependency-management" aria-label="Permalink to &quot;**Dependency Management**&quot;">​</a></h2><p>Manage dependencies in separate PRs with justification and security checks, and never commit logs, builds, or sensitive files.</p><h3 id="rules-3" tabindex="-1"><strong>Rules</strong> <a class="header-anchor" href="#rules-3" aria-label="Permalink to &quot;**Rules**&quot;">​</a></h3><p>All dependency updates must:</p><ol><li>Be isolated in separate PR</li><li>Include justification</li><li>Commit lock files</li><li>Pass security audit</li></ol><h3 id="prohibited" tabindex="-1"><strong>Prohibited</strong> <a class="header-anchor" href="#prohibited" aria-label="Permalink to &quot;**Prohibited**&quot;">​</a></h3><ul><li>Silent version bumps</li><li>Updating dependencies in feature PRs</li><li>Ignoring security warnings</li></ul><h2 id="prohibited-practices" tabindex="-1"><strong>Prohibited Practices</strong> <a class="header-anchor" href="#prohibited-practices" aria-label="Permalink to &quot;**Prohibited Practices**&quot;">​</a></h2><h3 id="never-commit" tabindex="-1"><strong>Never Commit</strong> <a class="header-anchor" href="#never-commit" aria-label="Permalink to &quot;**Never Commit**&quot;">​</a></h3><ul><li>Log files</li><li>Build artifacts</li><li>Database dumps</li><li>Temporary files</li><li>IDE configurations</li><li>Environment files with secrets</li></ul><h3 id="-4" tabindex="-1"><a class="header-anchor" href="#-4" aria-label="Permalink to &quot;&quot;">​</a></h3><h3 id="-5" tabindex="-1"><a class="header-anchor" href="#-5" aria-label="Permalink to &quot;&quot;">​</a></h3><h3 id="maintain-gitignore" tabindex="-1"><strong>Maintain .gitignore</strong> <a class="header-anchor" href="#maintain-gitignore" aria-label="Permalink to &quot;**Maintain .gitignore**&quot;">​</a></h3><p>node_modules/<br> dist/<br> build/<br> *.log<br> logs/<br> .env<br> .env.local<br> .vscode/<br> .idea/<br> .DS_Store</p><h3 id="git-is-not-backup" tabindex="-1"><strong>Git Is Not Backup</strong> <a class="header-anchor" href="#git-is-not-backup" aria-label="Permalink to &quot;**Git Is Not Backup**&quot;">​</a></h3><p>Do not use Git to store:</p><ul><li>Logs</li><li>Builds</li><li>Dumps</li><li>Temporary files</li></ul><h2 id="enforcement-1" tabindex="-1"><strong>Enforcement</strong> <a class="header-anchor" href="#enforcement-1" aria-label="Permalink to &quot;**Enforcement**&quot;">​</a></h2><p>Universal application, consequences for violations, and escalation procedures.</p><h3 id="universal-application" tabindex="-1"><strong>Universal Application</strong> <a class="header-anchor" href="#universal-application" aria-label="Permalink to &quot;**Universal Application**&quot;">​</a></h3><p>These standards apply to all team members including leads.</p><h3 id="consequences" tabindex="-1"><strong>Consequences</strong> <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;**Consequences**&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Violation</th><th>Action</th></tr></thead><tbody><tr><td>Missing commit standards</td><td>PR rejected</td></tr><tr><td>Identity misconfiguration</td><td>PR blocked until corrected</td></tr><tr><td>Force push to shared branch</td><td>Critical incident</td></tr><tr><td>Bypassing CI</td><td>PR rejected immediately</td></tr><tr><td>Unresolved conflicts</td><td>PR returned to author</td></tr></tbody></table><h3 id="code-review-culture" tabindex="-1"><strong>Code Review Culture</strong> <a class="header-anchor" href="#code-review-culture" aria-label="Permalink to &quot;**Code Review Culture**&quot;">​</a></h3><ul><li>git blame is for understanding history, not blaming people</li><li>Reviews focus on code, not individuals</li><li>Provide constructive feedback</li><li>Respect all contributors</li></ul><h3 id="escalation-path" tabindex="-1"><strong>Escalation Path</strong> <a class="header-anchor" href="#escalation-path" aria-label="Permalink to &quot;**Escalation Path**&quot;">​</a></h3><ol><li>First violation: Peer coaching</li><li>Second violation: Lead developer review</li><li>Third violation: Performance discussion</li><li>Pattern of violations: Management escalation</li></ol><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Full docs site (VitePress): <strong><a href="https://mediuswareltd.github.io/conventional-commit-spec/" target="_blank" rel="noreferrer">https://mediuswareltd.github.io/conventional-commit-spec/</a></strong></p><p>Local preview:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><hr><p>Repository: <a href="https://github.com/mediuswareltd/conventional-commit-spec" target="_blank" rel="noreferrer">mediuswareltd/conventional-commit-spec</a></p>`,161)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
